/* Hull can extend beyond the collision field. Its components are drawn in that field. */
/* A spatial wipe is the advancing environment boundary, not a blackout/fade.
   Scenery clocks and actors remain continuous; physical cave entry uses existing entryY. */
static int cavern_kind70(int k){return k==ENV_ROOT||k==ENV_HIVE||k==ENV_WRECK||k==ENV_MOUTH||k==ENV_TEETH||k==ENV_CRYSTAL;}
