static void draw_giant_form_at(int form,float opacity,float rootX,float rootY,float bank){if(opacity<=0)return;Giant*b=&ex.giant;int m=journey_number(),rows=b->archetype==1?24:1;float a=flight_view_angle(),w=(960-264*sideBlend)*journeyZoom,h=(696+264*sideBlend)*journeyZoom,scale=giant_world_scale(),damage=giant_damage_fraction(),flash=boss_flash_alpha(giant_damage_until()),tick=b->timer+visualTick-g.tick;SDL_Texture*t=form?giantForms:giantHulls;float uv[4]={(m%3)/3.0f,(m/3)/2.0f,1/3.0f,1/2.0f};if(form)memcpy(uv,giantFormsUV[form-1][m],sizeof(uv));for(int pass=0;pass<3;pass++){float alpha=opacity*(pass==0?1:pass==1?damage*.6f:flash);if(alpha<=0)continue;SDL_SetTextureColorMod(t,pass==1?22:255,pass==1?18:pass==2?25:255,pass==1?20:pass==2?35:255);nquad=0;for(int row=0;row<rows;row++){float yy=-96+192*row/(float)rows,hh=192.0f/rows;int first=nquad;quad((160+(rootX-176)*scale)*3,(100+(rootY+yy)*scale)*3,1056*scale,hh*scale*3,(SDL_FColor){1,1,1,alpha},uv[0],uv[1]+uv[3]*row/rows,uv[2],uv[3]/rows);if(rows>1)for(int v=first*4;v<nquad*4;v++){float localY=(vertices[v].position.y/3-100)/scale-rootY;vertices[v].position.x+=giant_flex_at(localY,tick)*scale*3;}}float ca=cosf(bank*PI/180),sa=sinf(bank*PI/180),cx=(160+rootX*scale)*3,cy=(100+rootY*scale)*3;for(int v=0;v<nquad*4;v++){float dx=vertices[v].position.x-cx,dy=vertices[v].position.y-cy;vertices[v].position.x=cx+dx*ca-dy*sa;vertices[v].position.y=cy+dx*sa+dy*ca;}for(int v=0;v<nquad*4;v++){float xx=(vertices[v].position.x-480)*w/960,yy=(vertices[v].position.y-420)*h/696;vertices[v].position.x=480+xx*cosf(a)-yy*sinf(a);vertices[v].position.y=420+xx*sinf(a)+yy*cosf(a);}flush(t);}SDL_SetTextureColorMod(t,255,255,255);}

