/* Quad geometry shares the pilot's final camera projection, including the
   tiny-pilot foreground pass. Bodies overlap nose/wing roots, never float ahead. */
static void globule_bar(float x,float y,float w,int r,int g,int b,int a){nquad=0;quad(x*3,y*3,w*3,2*3,(SDL_FColor){r/255.0f,g/255.0f,b/255.0f,a/255.0f},0,0,1,1);flush(NULL);}
static void draw_globules_attached(void){for(int n=0;n<3;n++)if(ex.globuleHP[n]){float x=globule_x(n),y=globule_y(n);nquad=0;quad((x-2)*3,(y+1)*3,12,9,(SDL_FColor){.4f,.6f,.2f,.6f},0,0,1,1);flush(NULL);journey_hit_cell(parasiteTexture,parasiteDamage,3,0,4,1,x,y,7,8,ex.globuleDamageUntil[n]);float bx=n==0?x-10:n==1?x+4:x-3,by=n==2?y-6:y-2;globule_bar(bx,by,6,25,18,15,230);globule_bar(bx,by,6*ex.globuleHP[n]/240.0f,255,190,80,245);}}
static void draw_journey_attached(void){for(int e=0;e<MAXE;e++)if(g.enemies[e].on&&g.enemies[e].dotTicks){nquad=0;quad(g.enemies[e].x/Q*3-36,g.enemies[e].y/Q*3-36,72,72,(SDL_FColor){.2f,.5f,1,.35f},0,0,1,1);flush(halo);}if(ex.repairFlash){nquad=0;quad(g.px/Q*3-70,player_y/Q*3-70,140,140,(SDL_FColor){.1f,1,.65f,ex.repairFlash/80.0f},0,0,1,1);flush(halo);}if(!zoomed_pilot_pass())draw_globules_attached();for(int i=0;i<ex.leeches;i++)journey_cell(parasiteTexture,i%2,0,4,1,parasite_x(i),parasite_y(i),11,12);if(journey_kind()==ENV_BEAST&&ex.env.timer%500>=400){int c=ex.env.timer%500;journey_rect(125,24,70,232,110,170,255,c<475?25:80);journey_line(125,24,125,256,130,220,255,170);journey_line(195,24,195,256,130,220,255,170);if(c>=475)for(int y=30;y<256;y+=16)journey_line(130+(y%7),y,190-(y%11),y+16,200,245,255,240);}}
